export const IGCSE_LIBRARY = [
  // Sciences (also in IGCSE_SCIENCES_LIBRARY for legacy compat)
  { match: /\bbiology\b/i,                       const_: IGCSE_BIOLOGY_0610,      source: 'IGCSE Biology — 130-lesson scheme (Cambridge 0610 & Edexcel 4BI1)' },
  // Chemistry is the first subject where the two boards genuinely differ:
  // Cambridge 0620 runs 74 lessons in 12 topics, Edexcel 4CH1 runs 72 in 4
  // sections. byCurriculum makes the loader pick the right one.
  { match: /\bchemistry\b/i,
    byCurriculum: {
      CambridgeIGCSE: { const_: IGCSE_CHEMISTRY_CAM, source: 'Cambridge IGCSE Chemistry 0620 — 74-lesson scheme' },
      EdexcelIGCSE:   { const_: IGCSE_CHEMISTRY_EDX, source: 'Edexcel International GCSE Chemistry 4CH1 — 72-lesson scheme' },
    },
    const_: IGCSE_CHEMISTRY_CAM, source: 'Cambridge IGCSE Chemistry 0620 — 74-lesson scheme' },
  { match: /\bphysics\b/i,                       const_: IGCSE_PHYSICS_0625,      source: 'Cambridge IGCSE Physics 0625' },
  // English subjects — order matters: ESL and Literature must be matched
  // BEFORE the broader English Language regex (otherwise "English Literature"
  // and "English as a Second Language" would match the Language pattern first)
  { match: /\b(esl|english\s+as\s+a?\s*second)\b/i, const_: IGCSE_ESL_0510,         source: 'Cambridge IGCSE English as a Second Language 0510' },
  { match: /\b(literature|english\s+lit)\b/i,    const_: IGCSE_ENGLISH_LIT_0475,  source: 'Cambridge IGCSE Literature in English 0475' },
  { match: /\benglish\b/i,                       const_: IGCSE_ENGLISH_LANG_0500, source: 'Cambridge IGCSE First Language English 0500' },
  // Business / Economics
  // Additional Mathematics MUST be tested before anything matching
  // "math", or "Additional Mathematics" would fall through to a plain
  // Maths matcher — which is exactly how this subject ended up carrying
  // the 0580 core spine. 0606 shares ZERO lessons with 0580: it is a
  // bridging course to A Level covering calculus, logarithms and
  // trigonometric identities that core Maths never touches.
  { match: /\badditional\s+math/i,           const_: IGCSE_ADD_MATHS_0606,   source: 'Cambridge IGCSE Additional Mathematics 0606 \u2014 124-lesson scheme' },
  { match: /\baccounting\b/i,                const_: IGCSE_ACCOUNTING_0452,  source: 'Cambridge IGCSE Accounting 0452 \u2014 126-lesson scheme' },

  // Modern foreign languages. Cambridge MFL syllabuses share a common
  // skeleton — five Areas of Experience, four skills — so these spines
  // are parallel BY DESIGN. The grammar strand is what genuinely
  // differs: German needs cases and word order, Swahili needs the noun
  // class system, and Swahili shares no grammar lesson with French.
  //
  // Swahili is matched before the others because "Swahili (Kiswahili)"
  // and "Kiswahili" are both live subject names in the catalogue.
  { match: /\b(swahili|kiswahili)\b/i,       const_: IGCSE_SWAHILI_0262, source: 'Cambridge IGCSE Swahili 0262 \u2014 130-lesson scheme' },
  { match: /\bfrench\b/i,                    const_: IGCSE_FRENCH_0520,  source: 'Cambridge IGCSE French 0520 \u2014 127-lesson scheme' },
  { match: /\bspanish\b/i,                   const_: IGCSE_SPANISH_0530, source: 'Cambridge IGCSE Spanish 0530 \u2014 127-lesson scheme' },
  { match: /\bgerman\b/i,                    const_: IGCSE_GERMAN_0525,  source: 'Cambridge IGCSE German 0525 \u2014 128-lesson scheme' },

  // ICT. Tested before Computer Science so a subject named
  // "Information & Communication Technology" can never fall through to
  // the Computer Science matcher. Cambridge 0417 is practical-heavy
  // (papers 2 and 3 are 60% of the marks); Edexcel 4IT1 weights digital
  // media and project work differently, so this is board-aware.
  { match: /\bict\b|information\s*&?\s*communications?\s+technology/i,
    byCurriculum: {
      CambridgeIGCSE: { const_: IGCSE_ICT_CAM, source: 'Cambridge IGCSE ICT 0417 \u2014 156-lesson scheme' },
      EdexcelIGCSE:   { const_: IGCSE_ICT_EDX, source: 'Edexcel International GCSE ICT 4IT1 \u2014 106-lesson scheme' },
    },
    const_: IGCSE_ICT_CAM, source: 'Cambridge IGCSE ICT 0417 \u2014 156-lesson scheme' },

  // Computer Science. Cambridge 0478 and Edexcel 4CP0 are genuinely
  // different schemes — Edexcel is Python-specific and carries a "bigger
  // picture" topic on ethics and environment that Cambridge spreads
  // elsewhere — so this is board-aware like Chemistry.
  { match: /\bcomputer\s*science\b|\bcomputing\b/i,
    byCurriculum: {
      CambridgeIGCSE: { const_: IGCSE_COMPSCI_CAM, source: 'Cambridge IGCSE Computer Science 0478 \u2014 144-lesson scheme' },
      EdexcelIGCSE:   { const_: IGCSE_COMPSCI_EDX, source: 'Edexcel International GCSE Computer Science 4CP0 \u2014 132-lesson scheme' },
    },
    const_: IGCSE_COMPSCI_CAM, source: 'Cambridge IGCSE Computer Science 0478 \u2014 144-lesson scheme' },
  { match: /\bbusiness\b/i,                      const_: IGCSE_BUSINESS_0450,     source: 'Cambridge IGCSE Business Studies 0450 — 118-lesson scheme' },
  { match: /\beconomics\b/i,                     const_: IGCSE_ECONOMICS_0455,    source: 'Cambridge IGCSE Economics 0455' },
  // Humanities
  { match: /\bgeography\b/i,                     const_: IGCSE_GEOGRAPHY_0460,    source: 'Cambridge IGCSE Geography 0460' },
  { match: /\bhistory\b/i,                       const_: IGCSE_HISTORY_0470,      source: 'Cambridge IGCSE History 0470 (Option B + Germany Depth)' },
  { match: /\bsociology\b/i,                     const_: IGCSE_SOCIOLOGY_0495,    source: 'Cambridge IGCSE Sociology 0495' },
]

/* ════════════════════════════════════════════════════════════════
 * CAMBRIDGE PRIMARY — YEAR 5 (STAGE 5) SPINES
 * Same shape and granularity as IGCSE_MATHS_0580: one subtopic
 * == one lesson, sequential 3-digit codes within a subject.
 *
 * These are DEEPER than the PRIMARY_* all-stage library above.
 * Those give one subtopic per stage per strand (planning level);
 * these give one subtopic per lesson (question-tagging level).
 * Loading a Year 5 spine REPLACES the subject's spine, so a
 * subject is either all-stage OR Year 5, not both.
 *
 * Question JSON should reference subtopic CODE (e.g. '5M.014')
 * rather than the long name — codes are stable, names may be
 * reworded.
 * ════════════════════════════════════════════════════════════ */

