// Cambridge International AS & A Level Biology 9700
// Lesson-level spine, 20 topics / 213 lessons.
//
// AS AND A2 ARE SEPARATED BY TOPIC PREFIX
// A Subject record holds one spine, and /syllabus/bulk replaces it
// wholesale, so AS and A2 cannot be two spines on one subject. Instead
// every topic is prefixed "AS ·" or "A2 ·". A teacher building an AS
// paper filters the question bank on "AS ·" and gets exactly the AS
// lessons; the same works in auto-homework and lesson practice. This
// mirrors how the Primary spines use "Year 5 ·".
//
// AS covers syllabus topics 1-11 and is examined in Papers 1-3.
// A2 covers topics 12-19 and is examined in Papers 4-5, but A2 papers
// assume the AS content throughout — which is why one continuous spine
// is the honest representation rather than two disconnected ones.
