// Cambridge International AS & A Level Law 9084
// Lesson-level spine, 13 topics / 154 lessons.
//
// SEQUENCING
// Legal method comes first and is not negotiable. A student who does
// not understand how precedent binds, or how a statute is interpreted,
// cannot reason about negligence or contract formation — they can only
// memorise outcomes. So sources of law, the court hierarchy and
// statutory interpretation are secured before any substantive law.
//
// AS covers the legal system and the law of contract. A2 adds tort and
// criminal law, both of which assume the AS treatment of precedent and
// legal reasoning throughout.
//
// CASE LAW IS TAUGHT AS PRINCIPLE, NOT AS A LIST
// Leading cases change less often than syllabuses do, but a spine that
// listed case names would still date. Each lesson is framed around the
// PRINCIPLE established, so a teacher files questions about whichever
// authorities they teach against the relevant principle.
