// Pearson Edexcel International A Level
//   Biology   (YBI11/WBI11) — 6 units / 154 lessons
//   Chemistry (YCH11/WCH11) — 6 units / 160 lessons
//
// WHY THESE ARE PREFIXED BY UNIT, NOT BY AS/A2
// Edexcel IAL is MODULAR. Candidates sit six separate unit examinations,
// often in different series, and may resit individual units. Units 1-3
// constitute the AS award and Units 4-6 complete the A Level, but the
// unit is what a student actually enters for and what a teacher plans
// towards. Prefixing "U1 ·" through "U6 ·" lets a teacher filter to the
// unit being taught this term — which AS/A2 prefixes could not express.
//
// UNITS 3 AND 6 ARE PRACTICAL EXAMINATIONS
// They are not coursework and not theory. They assess laboratory
// technique, data handling and experimental evaluation under exam
// conditions, and they carry real marks. Each gets its own unit here
// rather than a handful of lessons attached elsewhere.
//
// This is deliberately NOT the Cambridge spine relabelled. Edexcel
// groups content differently — immunity sits with microbiology in Unit
// 4, and organic nitrogen chemistry with transition metals in Unit 5 —
// and loading a Cambridge scheme here would misrepresent the course.

