// Pearson Edexcel International A Level
//   Physics     (YPH11/WPH11) — 6 units / 148 lessons
//   Mathematics (YMA01/WMA11) — modular, 176 lessons
//
// PHYSICS follows the same unit structure as IAL Biology and Chemistry.
//
// MATHEMATICS IS PREFIXED BY MODULE, NOT BY UNIT NUMBER
// Edexcel IAL Mathematics is the most modular qualification in the
// suite. A candidate builds an award from Pure modules plus applied
// modules, and centres choose very different combinations:
//
//   IAL Mathematics        = P1 + P2 + P3 + P4 + two applied
//   Common applied choices = M1 + S1,  or S1 + S2,  or M1 + M2,  or D1
//
// Prefixing "P1 ·" through "P4 ·", "M1 ·", "S1 ·", "S2 ·", "D1 ·" lets
// a centre teaching P1-P4 with M1 and S1 filter to exactly those and
// never see Decision Mathematics in its question bank.

