// ═══════════════════════════════════════════════════════════
// EDEXCEL INTERNATIONAL A LEVEL LIBRARY
// Separate from ALEVEL_LIBRARY because subject names are identical
// across the boards — "Biology" exists in both — and Edexcel IAL is
// unit-based where Cambridge is AS/A2. One combined list would let a
// Cambridge scheme load onto an Edexcel subject.
// ═══════════════════════════════════════════════════════════
// Pearson Edexcel International A Level
//   Business  (YBS11/WBS11) — 4 units / 128 lessons
//   Economics (YEC11/WEC11) — 4 units / 132 lessons
//
// FOUR UNITS, NOT SIX
// Unlike the IAL sciences, Business and Economics are examined through
// FOUR units rather than six, with no separate practical component.
// Units 1 and 2 give the AS award; Units 3 and 4 complete the A Level
// and are synoptic — they assume and draw on the first two throughout.
//
// The synoptic character of Units 3 and 4 matters for teaching. They are
// not new content areas so much as the same material examined at a
// strategic level with case-study evidence, which is why the evaluation
// and data-handling skills appear as their own lessons rather than being
// assumed.

