// Pearson Edexcel International A Level
//   Psychology (YPS01/WPS01) — 4 units / 132 lessons
//   Accounting (YAC11/WAC11) — 4 units / 130 lessons
//
// PSYCHOLOGY IS APPROACH-LED, NOT TOPIC-LED
// Edexcel structures IAL Psychology around psychological APPROACHES —
// social, cognitive, biological, learning — each taught with its own
// studies and methods, rather than around topics like memory or stress.
// Unit 3 then applies those approaches to health and clinical contexts.
// Structuring this by topic would cut across how the course is actually
// taught and examined.
//
// ACCOUNTING follows the same principle as the Cambridge spine: double
// entry and financial statements are secured before cost and management
// accounting, because the second depends entirely on the first.

